"""Data.lua emitter: writes companion data back into the addon folder.

Output contract (consumed by addon/DecadesSync/Data/DecadesData.lua, loaded
via the toc so it must ASSIGN the ``DecadesData`` global rather than return):

    -- Generated by decades-companion. DO NOT EDIT.
    DecadesData = {
        ["key"] = value,
        ...
    }

The value grammar is exactly what :mod:`companion.svparse` parses: string
keys, double-quoted strings with the escapes ``\\"`` ``\\\\`` ``\\n``,
integers, floats, booleans, ``nil``, nested tables, trailing commas.

The write is atomic: the text is serialized and validated in full first,
then written to a temporary file in the destination directory and moved
into place with :func:`os.replace`.
"""

import math
import os
import tempfile
from pathlib import Path

__all__ = ["emit_data_lua", "HEADER"]

HEADER = "-- Generated by decades-companion. DO NOT EDIT."


def _escape(text: str) -> str:
    """Escape a string literal using only the escapes svparse decodes."""
    return (
        text.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
    )


def _encode(value, depth: int) -> str:
    if value is None:
        return "nil"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return f'"{_escape(value)}"'
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise TypeError(f"non-finite float cannot be emitted: {value!r}")
        return repr(value)
    if isinstance(value, dict):
        indent = "\t" * depth
        inner = "\t" * (depth + 1)
        if not value:
            return "{}"
        lines = []
        for key in sorted(value):
            if not isinstance(key, str):
                raise TypeError(f"table keys must be str, got {type(key).__name__}")
            lines.append(f'{inner}["{_escape(key)}"] = {_encode(value[key], depth + 1)},')
        return "{\n" + "\n".join(lines) + f"\n{indent}}}"
    if isinstance(value, list):
        indent = "\t" * depth
        inner = "\t" * (depth + 1)
        if not value:
            return "{}"
        lines = [f"{inner}{_encode(item, depth + 1)}," for item in value]
        return "{\n" + "\n".join(lines) + f"\n{indent}}}"
    raise TypeError(f"unsupported value type: {type(value).__name__}")


def emit_data_lua(data: dict, out: Path) -> None:
    """Emit ``data`` as a Data.lua file assigning the DecadesData global.

    Serializes everything first (a bad payload raises before any file is
    touched), creates parent directories, then writes atomically via a
    temp file in the destination directory + :func:`os.replace`.
    """
    if not isinstance(data, dict):
        raise TypeError(f"data must be dict, got {type(data).__name__}")
    text = f"{HEADER}\nDecadesData = {_encode(data, 0)}\n"

    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)

    fd, tmp_name = tempfile.mkstemp(dir=out.parent, prefix=".DecadesData.", suffix=".tmp")
    tmp = Path(tmp_name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, out)
    except BaseException:
        tmp.unlink(missing_ok=True)
        raise
